/** Resource bundles: named groups loaded and released as one unit.
 *
 * A bundle is the unit a game actually thinks in — "the main menu", "the
 * forest level", "this player's cosmetics" — and it is plain serializable data
 * so it can be authored in the editor, generated by a build step, or produced
 * at runtime by a streaming system.
 *
 * The bundle owns the handles it loads. Releasing the bundle releases them all,
 * which is what makes "unload the level" a single call instead of a bookkeeping
 * exercise that leaks whatever the developer forgot.
 */
import type { ResourceHandle, ResourceKey } from "./handle.js";
import { formatResourceKey } from "./handle.js";
import type { LoadOptions, ResourceManager } from "./resource-manager.js";

export type ResourceBundleState = "unloaded" | "loading" | "loaded" | "failed";

export interface ResourceBundleData {
  readonly formatVersion: 1;
  readonly name: string;
  readonly resources: readonly ResourceKey[];
}

/** Validates authored bundle data, rejecting duplicates and empty ids so a
 * malformed bundle fails at load time with a clear message rather than half
 * loading. */
export function validateBundle(data: ResourceBundleData): ResourceBundleData {
  if (data.formatVersion !== 1) throw new Error(`Unsupported resource bundle version ${String(data.formatVersion)}.`);
  const name = data.name.trim();
  if (!name) throw new Error("A resource bundle requires a non-empty name.");
  const seen = new Set<string>();
  const resources = data.resources.map((resource) => {
    const type = resource.type.trim();
    const id = resource.id.trim();
    if (!type || !id) throw new Error(`Bundle "${name}" contains a resource with an empty type or id.`);
    const label = formatResourceKey({ type, id });
    if (seen.has(label)) throw new Error(`Bundle "${name}" lists ${label} more than once.`);
    seen.add(label);
    return { type, id };
  });
  return { formatVersion: 1, name, resources };
}

/**
 * A loaded-or-not group of resources.
 *
 * Loading is idempotent: calling {@link load} while already loading returns the
 * same promise, and calling it when loaded resolves immediately. That means a
 * streaming system can call it whenever a region becomes relevant without
 * tracking whether it already did.
 */
export class ResourceBundle {
  readonly #data: ResourceBundleData;
  readonly #manager: ResourceManager;
  #handles: ResourceHandle<unknown>[] = [];
  #state: ResourceBundleState = "unloaded";
  #pending: Promise<void> | undefined;

  constructor(manager: ResourceManager, data: ResourceBundleData) {
    this.#manager = manager;
    this.#data = validateBundle(data);
  }

  get name(): string {
    return this.#data.name;
  }

  get state(): ResourceBundleState {
    return this.#state;
  }

  get resources(): readonly ResourceKey[] {
    return this.#data.resources;
  }

  /** Handles for everything the bundle loaded. Retain one to keep a single
   * resource alive past the bundle's own lifetime. */
  get handles(): readonly ResourceHandle<unknown>[] {
    return this.#handles;
  }

  async load(options: LoadOptions = {}): Promise<void> {
    if (this.#state === "loaded") return;
    if (this.#pending) return this.#pending;
    this.#state = "loading";
    this.#pending = (async () => {
      try {
        this.#handles = await this.#manager.preload(this.#data.resources, options);
        this.#state = "loaded";
      } catch (error) {
        this.#state = "failed";
        throw new Error(`Resource bundle "${this.#data.name}" failed to load: ${messageOf(error)}`, { cause: error });
      } finally {
        this.#pending = undefined;
      }
    })();
    return this.#pending;
  }

  /** Releases every handle the bundle holds. Safe to call when unloaded. */
  release(): void {
    for (const handle of this.#handles) {
      if (!handle.released) handle.release();
    }
    this.#handles = [];
    this.#state = "unloaded";
  }
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
